def fit_table(problems, learners):
    # {problem: {learner: test accuracy rounded to 4 places}}
    # build each learner fresh with learners[name]()
    table = {}
    for p, (Xa, ya, Xb, yb) in problems.items():
        table[p] = {}
        for name, make in learners.items():
            m = make().fit(Xa, ya)
            table[p][name] = round(m.score(Xb, yb), 4)
    return table

