def choose_on_validation(X, y, X_test, y_test, learners, n_val):
    # validation accuracy for each learner, fitted on X[:-n_val];
    # a tie goes to the learner listed first;
    # refit the winner on all of X, y and return (name, test accuracy, 4 places)
    best, best_acc = None, -1.0
    for name, make in learners.items():
        acc = make().fit(X[:-n_val], y[:-n_val]).score(X[-n_val:], y[-n_val:])
        if acc > best_acc:
            best, best_acc = name, acc
    m = learners[best]().fit(X, y)
    return (best, round(m.score(X_test, y_test), 4))
